INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich den Ausbildungsvertrag vor Beginn kündigen?', 2, '[{"text": "Ja", "correct": true, "because": "Vor Beginn möglich"}, {"text": "Nein", "correct": false, "because": "Rechtlich erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Ausbildungsvertrag schriftlich sein?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Vorgabe"}, {"text": "Nein", "correct": false, "because": "Mündlich nicht gültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist meine Ausbildungsvergütung im Vertrag festgelegt?', 2, '[{"text": "Ja", "correct": true, "because": "Pflichtangabe"}, {"text": "Nein", "correct": false, "because": "Muss enthalten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich ohne Vertrag ausgebildet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Vertrag ist Voraussetzung"}, {"text": "Ja", "correct": false, "because": "Rechtlich nicht zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Muss ich im Vertrag Überstunden machen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Vereinbarung"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Betrieb den Vertrag einseitig ändern?', 2, '[{"text": "Nein", "correct": true, "because": "Beidseitige Zustimmung nötig"}, {"text": "Ja", "correct": false, "because": "Vertrag bindet beide"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Urlaub im Ausbildungsvertrag geregelt?', 2, '[{"text": "Ja", "correct": true, "because": "Pflichtangabe nach Gesetz"}, {"text": "Nein", "correct": false, "because": "Muss enthalten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich im Vertrag mehr als 40 Stunden pro Woche arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Jugendarbeitsschutz begrenzt"}, {"text": "Ja", "correct": false, "because": "Nur unter Ausnahmen"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was muss im Ausbildungsvertrag zwingend stehen?', 2, '[{"text": "Ausbildungsbeginn", "correct": true, "because": "Gesetzliche Pflicht"}, {"text": "Lieblingsessen", "correct": false, "because": "Irrelevant"}, {"text": "Hobbys", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, ich muss länger bleiben. Was regelt das im Vertrag?', 3, '[{"text": "Arbeitszeit", "correct": true, "because": "Definiert Arbeitsdauer"}, {"text": "Pausen", "correct": false, "because": "Nur Teilaspekt"}, {"text": "Urlaub", "correct": false, "because": "Anderes Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz schützt meine Rechte im Ausbildungsvertrag?', 2, '[{"text": "Berufsbildungsgesetz", "correct": true, "because": "Regelt Ausbildung"}, {"text": "BGB", "correct": false, "because": "Allgemeines Recht"}, {"text": "Steuergesetz", "correct": false, "because": "Finanzthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter will den Vertrag kündigen. Was gilt?', 3, '[{"text": "Frist von 4 Wochen", "correct": true, "because": "Gesetzliche Kündigungsfrist"}, {"text": "Sofort möglich", "correct": false, "because": "Nur bei schwerem Grund"}, {"text": "Ein Jahr warten", "correct": false, "because": "Zu lang"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten habe ich laut Ausbildungsvertrag?', 4, '[{"text": "Lernpflicht", "correct": true, "because": "Wissen aneignen"}, {"text": "Arbeitsbereitschaft", "correct": true, "because": "Mitwirken im Betrieb"}, {"text": "Anweisungen befolgen", "correct": true, "because": "Pflicht gegenüber Betrieb"}, {"text": "Kaffee kochen", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört in einen Ausbildungsvertrag?', 3, '[{"text": "Dauer der Ausbildung", "correct": true, "because": "Pflichtangabe"}, {"text": "Vergütung", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Probezeit", "correct": true, "because": "Üblicher Bestandteil"}, {"text": "Lieblingsfarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Streit über Arbeitszeiten. Was steht im Vertrag?', 3, '[{"text": "Reguläre Arbeitszeit", "correct": true, "because": "Muss definiert sein"}, {"text": "Überstundenregelung", "correct": true, "because": "Kann enthalten sein"}, {"text": "Pausenregelung", "correct": true, "because": "Gesetzlich relevant"}, {"text": "Freizeitgestaltung", "correct": false, "because": "Kein Vertragsinhalt"}]'),
('00000000-0000-00-0000-000000000000', 'Welche Rechte sichert mir der Ausbildungsvertrag?', 4, '[{"text": "Vergütung", "correct": true, "because": "Gesetzlich garantiert"}, {"text": "Urlaub", "correct": true, "because": "Mindestanspruch"}, {"text": "Ausbildung", "correct": true, "because": "Zweck des Vertrags"}, {"text": "Dienstwagen", "correct": false, "because": "Nicht Standard"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Vertrag regelt die Probezeit. b) Ich kann jederzeit kündigen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Probezeit ja, Kündigung fristgebunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betrieb muss mich ausbilden. b) Meine Arbeitszeit ist unbegrenzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausbildung Pflicht, Zeit begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Vertrag muss bei der IHK gemeldet werden. b) Vergütung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Meldung ja, Vergütung Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ich habe Anspruch auf Urlaub. b) Der Vertrag kann mündlich sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Urlaub ja, Schriftform Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

